func main() {
	d := idfy.New(IdfyConfig{}, newrelic.Agent{}, httpclient.NewHttpClient(30))
	res, err := d.MaskAadharDoc(context.Background(), "id", idfy.MaskAadharDocRequest{
		TaskID:  uuid.New().String(),
		GroupID: uuid.New().String(),
		Data: struct {
			Consent        string "json:\"consent\""
			Document1      string "json:\"document1\""
			LastFourDigits bool   "json:\"last_four_digits\""
			MaskAllDigits  bool   "json:\"mask_all_digits\""
			MaskQr         bool   "json:\"mask_qr\""
		}{
			Consent:   "yes",
			MaskQr:    true,
			Document1: "",
		},
	}, "4234")
	if err != nil {
		fmt.Println("Error in calling idfy api")
	}
	prettyJSON(res)
}

func prettyJSON(res *idfy.MaskAadharDocResponse) {
	jsonBytes, err := json.MarshalIndent(res, "", "  ")
	if err != nil {
		fmt.Println("Error marshaling JSON:", err)
		return
	}
	fmt.Println(string(jsonBytes))
}
